import { EntityPicker, Field, FieldLabel } from "@basis/ui";

interface Issuer {
  readonly id: string;
  readonly name: string;
}

const issuers: readonly Issuer[] = [{ id: "ust", name: "US Treasury" }];

<Field>
  <FieldLabel htmlFor="issuer">Issuer</FieldLabel>
  <EntityPicker
    id="issuer"
    search={async (text) =>
      Promise.resolve(issuers.filter((issuer) => issuer.name.toLowerCase().includes(text.toLowerCase())))
    }
    itemKey={(issuer) => issuer.id}
    itemLabel={(issuer) => issuer.name}
    onValueChange={() => undefined}
  />
</Field>;

import { Field, FieldLabel, SecurityPicker } from "@basis/ui";

interface Security {
  readonly cusip: string;
  readonly description: string;
}

<Field>
  <FieldLabel htmlFor="security">Security</FieldLabel>
  <SecurityPicker
    id="security"
    search={async () => Promise.resolve<readonly Security[]>([])}
    itemKey={(security) => security.cusip}
    itemLabel={(security) => security.description}
  />
</Field>;

import { FileImport, amountSchema, parSuffixes } from "@basis/ui";
import { z } from "zod";

const positionRow = z.object({ cusip: z.string(), par: amountSchema(parSuffixes) });

<FileImport
  schema={positionRow}
  headers={{ par: ["Par", "Par amount"] }}
  onImport={async () => {
    await Promise.resolve();
  }}
/>;

import { CellBar, Num } from "@basis/ui";

// A loss of 2.5 million in a column whose largest magnitude is 10 million.
<CellBar value={-2_500_000} max={10_000_000} signed>
  <Num value={-2_500_000} />
</CellBar>;

import { QueryState } from "@basis/ui";

// A query result as useQuery gives it; here, two positions fetched a minute ago.
const positions = {
  data: [{ cusip: "912828C57", par: 5_000_000 }, { cusip: "037833100", par: 2_000_000 }],
  dataUpdatedAt: Date.now() - 60_000,
  error: null,
  isPending: false,
  refetch: () => undefined,
};

<QueryState query={positions} emptyTitle="No positions" staleAfter={{ minutes: 15 }}>
  {(rows) => (
    <ul>
      {rows.map((row) => (
        <li key={row.cusip}>{row.cusip}</li>
      ))}
    </ul>
  )}
</QueryState>;

